class Solution {
    vector<int> nums,memo;
    int gcdValue(int a,int b){
        return b?gcdValue(b,a%b):a;
    }
    int dfs(int mask){
        if(mask==(1<<(int)nums.size())-1)return 0;
        if(memo[mask]>=0)return memo[mask];
        int operation=__builtin_popcount(mask)/2+1,best=0;
        for(int first=0;first<(int)nums.size();++first)if(!(mask&(1<<first)))for(int second=first+1;second<(int)nums.size();++second)if(!(mask&(1<<second)))best=max(best,operation*gcdValue(nums[first],nums[second])+dfs(mask|(1<<first)|(1<<second)));
        return memo[mask]=best;
    }
    public:int maxScore(vector<int>& input){
        nums=input;
        memo.assign(1<<nums.size(),-1);
        return dfs(0);
    }
};
